const client = ldapjs.createClient({ url: baseURL })

tap.before(() => {
  return new Promise((resolve, reject) => {
    client.bind('cn=admin,dc=planetexpress,dc=com', 'GoodNewsEveryone', (err) => {
      if (err) {
        return reject(err)
      }
      resolve()
    })
  })
})

